To create a basic password cracking program, we can use a brute-force approach with word combinations and some optimizations. Here's a Python program that attempts to crack a password by trying common words with various modifications:

```python
import sys
from itertools import product

def crack_password():
    common_words = ["password", "hello", "123456", "admin", "user", "test", "12345", "password1"]
    possible_additions = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890!@#$%^&*()"
    max_length = 12  # Maximum password length to try

    for length in range(6, max_length + 1):
        for word in common_words:
            if len(word) >= length:
                guess = word[:length]
                if guess == sys.argv[1]:
                    print("Password cracked: " + guess)
                    return
                # Try adding characters to the guess
                for i in range(len(guess)):
                    for c in possible_additions:
                        if i == 0:
                            modified_guess = c + guess[1:]
                        elif i == len(guess):
                            modified_guess = guess + c
                        else:
                            modified_guess = guess[:i] + c + guess[i:]
                        if modified_guess == sys.argv[1]:
                            print("Password cracked: " + modified_guess)
                            return
        # Try padding with random characters
        for i in range(0, max_length - len(word)):
            char = possible_additions[i]
            guess = word + char
            if guess == sys.argv[1]:
                print("Password cracked: " + guess)
                return

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python crack_password.py <password>")
        sys.exit(1)
    crack_password()
```

