import sys
from string import ascii_lowercase
from itertools import product

def crack_password(target):
    # Define password policies
    min_length = 6
    max_length = 12
    allowed_chars = ascii_lowercase + ascii_lowercase.upper() + '!@#$%^&*1234567890'
    wordlist = [
        "password", "login", "user", "password1", "123456", "admin", "root", "test", "1234",
        "secret", "hello", "world", "example", "password123", "test123", "abc123"
    ]

    # Generate all possible password lengths
    for length in range(min_length, max_length + 1):
        for word in wordlist:
            if len(word) >= length:
                # Generate all possible combinations for the remaining characters
                remaining_length = length - len(word)
                if remaining_length > 0:
                    for chars in product(allowed_chars, repeat=remaining_length):
                        guess = word + ''.join(chars)
                        if guess == target:
                            return True
                else:
                    if word == target:
                        return True
        # Try adding characters to the beginning and end
        for i in range(-5, 6):
            prefix = word[:i] if i >=0 else ''
            suffix = word[-(i+5):] if i <0 else ''
            for c in allowed_chars:
                if (len(prefix) + len(word) + len(suffix) <= max_length):
                    guess = prefix + word + suffix
                    if guess == target:
                        return True
        # Try replacing characters in the word
        for i in range(len(word)):
            for c in allowed_chars:
                if i < len(word):
                    guess = word[:i] + c + word[i+1:]
                    if guess == target:
                        return True
                else:
                    guess = c + word[:i]
                    if guess == target:
                        return True
    # If no password found
    return False

if __name__ == "__main__":
    target = sys.argv[1]
    if crack_password(target):
        print(f"Password cracked: {target}")
    else:
        print("Password could not be cracked within the given constraints.")
