from itertools import product
import getpass

def crack_password(username, password):
    # Dictionary of common words and variations
    common_words = ["password", "12345", "password123", "admin", "user", "test", "test123"]
    # Common suffixes to append
    suffixes = ["", "1", "2", "!", "@", "#", "$", "%", "0", "123"]

    # Try different password lengths
    for length in range(6, 13):
        # Generate all possible combinations
        for word in common_words:
            if len(word) >= length:
                base = word
                for suffix in suffixes:
                    if len(base) + len(suffix) == length:
                        test_pass = base + suffix
                        if test_pass == password:
                            return test_pass
        # Generate all possible lengths and create all possible passwords
        for l in range(1, length+1):
            for word in common_words:
                if len(word) == l:
                    for suffix in suffixes:
                        test_pass = word + suffix
                        if test_pass == password:
                            return test_pass
        # Try combinations of two words
        for word1 in common_words:
            for word2 in common_words:
                combined = word1 + word2
                for suffix in suffixes:
                    test_pass = combined + suffix
                    if test_pass == password:
                        return test_pass
        # Try permutations of words
        for i in range(len(common_words)):
            for j in range(i):
                perm = word[j] + word[i]
                for suffix in suffixes:
                    test_pass = perm + suffix
                    if test_pass == password:
                        return test_pass
    # If none found, suggest using a larger dictionary or other methods
