```python
import string
import sys

def crack_password(password):
    # Define the dictionary of common words
    common_words = ["password", "user", "login", "123456", "admin", "test", "123", "root"]

    # Define characters to append
    chars = string.ascii_letters + string.digits + "!@#$%^&*"

    # Try different lengths from 6 to 12
    for length in range(6, 13):
        # Generate all possible variations for this length
        for word in common_words:
            if len(word) >= length:
                # Generate base password
                base = word[:length]
                # Try different cases
                for case in [base, base.upper(), base.lower(), base.capitalize(), base.capitalize().lower()]:
                    # Try appending characters
                    for c in chars:
                        guess = case + c
                        if len(guess) == length:
                            yield guess
                            break
                # Try without appending
                yield base
            else:
                # Pad with characters if word is shorter
                for i in range(length - len(word)):
                    for c in chars:
                        guess = word + c
                        yield guess
        # Try combinations of different word lengths
        for i in range(len(common_words)):
            for j in range(i+1, len(common_words)):
