import os
import string
import sys

def generate_variations(word, length):
    allowed_chars = string.ascii_letters + string.digits + string.punctuation
    variations = set()
    word_length = len(word)
    if word_length == 0:
        return [chr(c) for c in range(1, length + 1)]
    # Generate all possible variations by appending characters
    for c in allowed_chars:
        variation = word + c
        if len(variation) == length:
            variations.add(variation)
    # Generate all possible variations by prepending characters
    for c in allowed_chars:
        variation = c + word
        if len(variation) == length:
            variations.add(variation)
    # Generate all possible variations by replacing each character
    for i in range(min(word_length, length)):
        for c in allowed_chars:
            if c != word[i]:
                variation = word[:i] + c + word[i+1:]
                if len(variation) == length:
                    variations.add(variation)
    return variations

def crack_password(target):
