            for i in range(len(word)):
                if i >= num:
                    break
                variations.append(word + (num - i - 1) * '0' + (
                    word[i] if i < len(word) else '0'
                ) + ''.join([chr(123 + c) for c in range(num - len(word)) if len(word) > i])
    return variations

def check_password(target, guess):
