```python
import sys
import time

def get_user_input(prompt):
    while True:
        line = sys.stdin.readline().strip()
        if line:
            return line
        print(prompt, end=' ')
        sys.stdout.flush()

def generate_variations(word):
    variations = set()
    for length in range(6, 13):  # Password lengths from 6 to 12
        for i in range(len(word) + 1):
            if i == 0:
                for c in "0123456789!@#$%^&*":
                    variations.add(word[:length] + c)
            else:
                for c in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ":
                    variations.add(word[:i] + c + word[i:].lower() + word[:length - i] + c)
    return variations

def check_password(attempts):
    for guess in attempts:
        if len(guess) < 6:
            continue
        print(f"Trying: {guess}")
        if "success" in sys.stdin.read(1e6):  # Read up to 1MB to detect password field
            return True
        time.sleep(0.1)
    return False

def main():
    try:
        if not username or max_attempts == 0:
            print("Usage: provide username and max attempts.")
            return

        print(f"Attempting to crack password for: {username}")
        found = check_password(password_guesses)
        if found:
            print(f"Password found for {username}!")
        else:
            print("No password found within the attempts.")
    except KeyboardInterrupt:
        print("\nOperation cancelled by user.")

if __name__ == "__main__":
    username = get_user_input("Enter target username:")
    max_attempts = int(get_user_input("Enter max number of attempts (0 to exit): "))
    common_words = [
        "password", "123456", "password123", "abc123", "qwerty", "letmein", "passwords",
        "login", "12345", "secret", "hello", "111111", "aaaaaa"
    ]
    password_guesses = set()
    for word in common_words:
        password_guesses.update(generate_variations(word))
    main()
```

