    for length in range(6, 13):
        # Generate all combinations of the given length
        for chars in words:
            if len(chars) >= length:
                password = chars
                if len(password) < length:
                    password += ''.join(random.choice(all_chars) for _ in range(length - len(password)))
            else:
                password = ''.join(random.choice(all_chars) for _ in range(length))

            # Try variations of the password with common suffixes
            base = password
            for i in range(1, 4):
                if len(base) + i <= length:
                    password = base + str(i)
                else:
                    password = base
                # Try adding a common suffix
                for j in range(1, 4):
                    if len(password) + j <= length:
                        password = password + str(j)
                    else:
                        password = password
                    # Try adding a common symbol
