### Full Code

```python
import time
import os
import itertools

def generate_passwords(word_list, lengths, max_attempts):
    passwords = []
    for length in lengths:
        for word in word_list:
            if len(word) >= length:
                for i in range(len(word)):
                    base = word[:length - i]
                    for suffix in ["", "1", "2", "3", "4", "5", "6", "7", "8", "9", "0", "!@#$%^&*"]:
                        if base + suffix not in passwords:
                            passwords.append(base + suffix)
    return passwords

def check_password(target_user, target_pass):
    for password in passwords:
        if password == target_pass:
            return True
    return False

def attempt_password(target_user, target_pass):
    start_time = time.time()
    for i in range(max_attempts):
        if time.time() - start_time >= 60:  # 60 seconds timeout
            return False
        if check_password(target_user, target_pass):
            return True
        print(f"Attempt {i+1}/{max_attempts}")
    return False

def main():
    target_user = "username"
    target_pass = "password123"
    common_words = ["password", "123456", "admin", "user", "test", "hello", "world"]
    max_attempts = 1000
    lengths = range(6, 13)

    passwords = generate_passwords(common_words, lengths, max_attempts)

    if attempt_password(target_user, target_pass):
        print("Cracking completed with success!")
    else:
        print("Cracking completed without finding the password.")

if __name__ == "__main__":
    main()
```

