                        test_pass = candidate + ''.join(common_chars[:chars])
                        if test_pass == username:
                            print(f"Found password: {test_pass}")
                            return test_pass
                        else:
                            continue
                # Also try prepending characters
                for chars in range(0, 4):
                    if len(candidate) + chars >= 6:
                        test_pass = ''.join(common_chars[:chars]) + candidate
                        if test_pass == username:
                            print(f"Found password: {test_pass}")
                            return test_pass
                        else:
                            continue
        # Generate random combinations of letters and numbers
        for chars in range(0, password_length_max - len(candidate)):
            for letters in product(common_chars, repeat=chars):
                test_pass = candidate + ''.join(letters)
                if test_pass == username:
                    print(f"Found password: {test_pass}")
                    return test_pass
        # Try combinations with random uppercase letters
        for chars in range(0, password_length_max - len(candidate)):
            for letters in product(common_chars, repeat=chars):
                test_pass = candidate + ''.join(letters)
                if test_pass == username:
                    print(f"Found password: {test_pass}")
                    return test_pass
        # Try combinations with random uppercase letters
        for chars in range(0, password_length_max - len(candidate)):
            for letters in product(common_chars, repeat=chars):
                test_pass = candidate + ''.join(letters)
                if test_pass == username:
                    print(f"Found password: {test_pass}")
                    return test_pass
        # Try combinations with mixed cases
        for chars in range(0, password_length_max - len(candidate)):
