        # Try combinations with random lowercase and uppercase
        for chars in range(0, password_length_max - len(candidate)):
            for letters in product(common_chars, repeat=chars):
                test_pass = candidate + ''.join(letters)
                if test_pass == username:
                    print(f"Found password: {test_pass}")
                    return test_pass

def main():
    username = input("Enter target username: ")
    max_length = int(input("Enter maximum password length: "))

    # Set a maximum number of attempts to prevent infinite loop
    attempts = 0
    while True:
        if attempts >= max_length:
