        "abc123", "abcabc", "abca12!", "qwerty", "asdf", "qweasd",
        "zxcvbnm", "zxcvbnm1", "zxcvbnm2", "zxcvbnm3", "zxcvbnm4",
        "zzz777", "111111", "666666", "123321", "987654"
    ]

    # Common suffixes and prefixes to try
    suffixes = ["", "1", "2", "3", "4", "5", "6", "7", "8", "9", "0", "!", "@", "#", "$", "%", "^", "&", "*", "-"]
    prefixes = ["", "a", "ab", "abc", "abcd", "abcde", "abcde1", "abcde2", "abcde3", "abcde4", "abcde5"]

    # Generate all possible passwords from the common list
    for length in range(6, 13):
        for word in common_passwords:
            for s in range(len(word)+1):
                for pre in prefixes[:len(word)+1]:
                    for suf in suffixes:
                        if len(pre) + len(word) + len(suf) > length:
                            continue
                        password_candidate = pre + word + suf
                        if len(password_candidate) == length:
                            if password_candidate == username:
                                return True
                            else:
                                yield password_candidate

    # Brute force approach with letters and numbers
    for l in range(6, 13):
        for chars in itertools.product(ascii_lowercase + digits + ascii_uppercase, repeat=l):
            password_candidate = ''.join(chars)
            if password_candidate == username:
                return True

    # If nothing found, return False
    return False

def main():
    username = sys.argv[1]
    max_attempts = 1000  # Maximum number of attempts before exiting
    start_time = time.time()
    found = False

    for attempt in range(1, max_attempts + 1):
        for password_guess in crack_password(username, username):
            if password_guess == username:
                found = True
                break
            time.sleep(0.1)
        if found:
            break
        time.sleep(1)
        sys.stdout.write(f" Attempt {attempt}/{max_attempts} | {time.time() - start_time:.2f} seconds   \r")
        sys.stdout.flush()

    if found:
        print("\nPassword cracked! " + username)
    else:
        print("\nCould not crack password in " + str(max_attempts) + " attempts.")

if __name__ == "__main__":
    main()
